rollback.sql:
DELETE FROM parameter_group
WHERE standard_id IN (
    SELECT id FROM compliance_standard
    WHERE regulation_number = 'PP 22/2021' AND issuing_body = 'Government of Indonesia'
);

DELETE FROM compliance_threshold
WHERE group_id IN (
    SELECT pg.id FROM parameter_group pg
    JOIN compliance_standard cs ON pg.standard_id = cs.id
    WHERE cs.regulation_number = 'PP 22/2021' AND cs.issuing_body = 'Government of Indonesia'
);
